import { useState, useCallback, memo, useEffect } from 'react';
import '../styles/searchForm.css';

// Конфигурация API
const GEONAMES_USERNAME = 'bobby0618'; // Замените на ваш username от GeoNames
const API_URL = `http://api.geonames.org/searchJSON?featureClass=P&country=RU&maxRows=10&username=${GEONAMES_USERNAME}&q=`;

const SearchForm = memo(({ 
  onSearch, 
  initialValues,
  wide, 
  isLoading
}) => {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [date, setDate] = useState('');
  const [showFromSuggestions, setShowFromSuggestions] = useState(false);
  const [showToSuggestions, setShowToSuggestions] = useState(false);
  const [fromSuggestions, setFromSuggestions] = useState([]);
  const [toSuggestions, setToSuggestions] = useState([]);
  const [isFetchingCities, setIsFetchingCities] = useState(false);
  const [error, setError] = useState(null);

  // Инициализация начальных значений
  useEffect(() => {
    setFrom(initialValues.from || '');
    setTo(initialValues.to || '');
    setDate(initialValues.date || '');
  }, [initialValues.from, initialValues.to, initialValues.date]);

  // Функция для отправки формы
  const handleSubmit = useCallback((e) => {
    e.preventDefault();
    if (!isLoading && from && to) {
      onSearch({ from, to, date });
    }
  }, [from, to, date, onSearch, isLoading]);

  // Функция для получения городов из API
  const fetchCities = useCallback(async (query) => {
    if (!query || query.length < 2) return [];
    
    try {
      setIsFetchingCities(true);
      setError(null);
      
      const response = await fetch(`${API_URL}${encodeURIComponent(query)}`);
      
      if (!response.ok) {
        throw new Error(`Ошибка HTTP: ${response.status}`);
      }
      
      const data = await response.json();
      
      if (!data.geonames) {
        throw new Error('Неверный формат данных от API');
      }
      
      return data.geonames.map(city => ({
        name: city.name,
        region: city.adminName1
      }));
    } catch (err) {
      console.error('Ошибка при загрузке городов:', err);
      setError('Не удалось загрузить список городов. Попробуйте позже.');
      return [];
    } finally {
      setIsFetchingCities(false);
    }
  }, []);

  // Дебаунс функция
  const debounce = (func, delay) => {
    let timer;
    return function(...args) {
      clearTimeout(timer);
      timer = setTimeout(() => func.apply(this, args), delay);
    };
  };

  // Оптимизированные обработчики с дебаунсом
  const handleFromInput = useCallback(debounce(async (value) => {
    setFrom(value);
    if (value.length >= 2) {
      const cities = await fetchCities(value);
      setFromSuggestions(cities);
    } else {
      setFromSuggestions([]);
    }
  }, 300), [fetchCities]);

  const handleToInput = useCallback(debounce(async (value) => {
    setTo(value);
    if (value.length >= 2) {
      const cities = await fetchCities(value);
      setToSuggestions(cities);
    } else {
      setToSuggestions([]);
    }
  }, 300), [fetchCities]);

  // Обработчики изменений инпутов
  const handleFromChange = useCallback((e) => {
    const value = e.target.value;
    setFrom(value);
    handleFromInput(value);
  }, [handleFromInput]);

  const handleToChange = useCallback((e) => {
    const value = e.target.value;
    setTo(value);
    handleToInput(value);
  }, [handleToInput]);

  const handleDateChange = useCallback((e) => {
    setDate(e.target.value);
  }, []);

  // Выбор города из списка
  const selectCity = useCallback((setCity, setShowSuggestions, cityName) => {
    setCity(cityName);
    setShowSuggestions(false);
  }, []);

  return (
    <div className="search-form-container">
      <form onSubmit={handleSubmit} className={`search-form ${wide ? 'wide' : ''}`}>
        {wide && <h2 className="form-title">Поиск билетов</h2>}
        
        {error && (
          <div className="error-message">
            {error}
            <button onClick={() => setError(null)}>×</button>
          </div>
        )}
        
        <div className="form-grid">
          <div className="input-group">
            <label htmlFor="from">Откуда</label>
            <div className="input-wrapper">
              <input
                id="from"
                name="from"
                value={from}
                onChange={handleFromChange}
                onFocus={() => setShowFromSuggestions(true)}
                onBlur={() => setTimeout(() => setShowFromSuggestions(false), 200)}
                placeholder="Город отправления"
                autoComplete="off"
                disabled={isFetchingCities}
              />
              {showFromSuggestions && (isFetchingCities || fromSuggestions.length > 0) && (
                <ul className="suggestions">
                  {isFetchingCities ? (
                    <li className="loading">Загрузка...</li>
                  ) : (
                    fromSuggestions.map(city => (
                      <li 
                        key={`${city.name}-${city.region}`} 
                        onClick={() => selectCity(setFrom, setShowFromSuggestions, city.name)}
                      >
                        {city.name} {city.region ? `(${city.region})` : ''}
                      </li>
                    ))
                  )}
                </ul>
              )}
            </div>
          </div>

          <div className="input-group">
            <label htmlFor="to">Куда</label>
            <div className="input-wrapper">
              <input
                id="to"
                name="to"
                value={to}
                onChange={handleToChange}
                onFocus={() => setShowToSuggestions(true)}
                onBlur={() => setTimeout(() => setShowToSuggestions(false), 200)}
                placeholder="Город прибытия"
                autoComplete="off"
                disabled={isFetchingCities}
              />
              {showToSuggestions && (isFetchingCities || toSuggestions.length > 0) && (
                <ul className="suggestions">
                  {isFetchingCities ? (
                    <li className="loading">Загрузка...</li>
                  ) : (
                    toSuggestions.map(city => (
                      <li 
                        key={`${city.name}-${city.region}`} 
                        onClick={() => selectCity(setTo, setShowToSuggestions, city.name)}
                      >
                        {city.name} {city.region ? `(${city.region})` : ''}
                      </li>
                    ))
                  )}
                </ul>
              )}
            </div>
          </div>

          <div className="input-group date-group">
            <label htmlFor="date">Дата (необязательно)</label>
            <div className="input-wrapper">
              <input
                id="date"
                name="date"
                type="date"
                value={date}
                onChange={handleDateChange}
                min={new Date().toISOString().split('T')[0]}
              />
            </div>
          </div>
        </div>

        <div className="search-button-container">
          <button 
            type="submit" 
            className="search-button"
            disabled={!from || !to || isLoading || isFetchingCities}
          >
            {isLoading ? 'Загрузка...' : 'Найти билеты'}
          </button>
        </div>
      </form>
    </div>
  );
});

export default SearchForm;
